  gap: 3px; 
  position: relative;
  border-radius: 8px;
  overflow: hidden;

    height: calc((98vw + 2px)/0.9585);

}
.story-grid-left {
  flex: 1 1 70%;
}
.story-grid-right {
  flex: 1 1 30%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  position: relative;
  overflow: hidden;
}
.story-grid-right-item {
  height: 50%;
}
.story-grid-more-products {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    right: 20px;
    position: absolute;
    bottom: 20px;
    gap: 4px;
}
.story-grid-left-text{
 flex: 1 1 30%;
 background: linear-gradient(180deg, #FFFFFF 4%, #D7D7D7 100%);
 backdrop-filter: blur(4px);
}
.left-text {
    font-weight: 500;
    font-size: 16px;
    line-height: 106%;
    vertical-align: middle;
    font-variant: small-caps;
    color: #000000;
    padding: 4px;
    align-items: center;
    justify-content: center;
    display: flex;
}
.bottom-gradient-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 15%;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.9), transparent);
  pointer-events: none;
}










        Limeroad Exclusive Story




























  document.getElementById("shareButton_58").addEventListener("click", () => {
    const shareData = {"title":"Don't miss out!","text":"Checkout this amazing Limeroad Exclusive Story on Limeroad at Limeroad!","url":"https://www.limeroad.com"}
    // Check if the Web Share API is supported
    if (navigator.share) {
      navigator.share(shareData)
        .then(() => console.log("Content Shared successfully!"))
        .catch((error) => console.error("Error sharing content:", error));
    } else {
      navigator.clipboard.writeText(shareData.url).then(() => {
        console.log("Text copied to clipboard");
      }).catch((error) => {
        console.error("Failed to copy text:", error);
      });
    }
  });

